import { invoke } from "@tauri-apps/api/core";
export interface FormatConvertTask {
  /** 待转换源文件物理绝对路径 */
  input_path: string;
  /** 目标扩展名 (如 mp3, flac, json, md, docx, epub, ico, pdf, extract 等) */
  target_format: string;
  /** 可选输出目录，未指定时默认输出到源文件同级目录 */
  output_dir?: string | null;
}
export interface FormatConvertResult {
  /** 是否转换成功 */
  success: boolean;
  /** 源文件路径 */
  input_path: string;
  /** 转换产物输出物理路径 */
  output_path?: string | null;
  /** 实际嗅探/转换的格式 */
  detected_format: string;
  /** 异常或成功描述信息 */
  message?: string | null;
}
export async function runFormatConvert(task: FormatConvertTask): Promise<FormatConvertResult> {
  return await invoke<FormatConvertResult>("run_format_convert", { task });
}// 🛡️ 紫电 AI 桌面工坊 - 4K/8K 视觉超分专属强类型契约 (upscale-48k.ts)
import { invoke } from "@tauri-apps/api/core";
export interface UpscaleTask {
  /** 待超分输入图像物理绝对路径 */
  input_path: string;
  /** 超分结果输出物理绝对路径 */
  output_path: string;
  /** 可选指定的 ONNX 模型物理路径 */
  model_path?: string | null;
  /** 目标放大倍率 (如 2.0, 4.0, 8.0) */
  target_scale?: number | null;
  /** 智能封顶最大物理边长 (4K 极速: 3840, 8K 旗舰: 8192) */
  max_output_side?: number | null;
  /** 切块网格尺寸 (默认 256 或 512) */
  tile_size?: number | null;
  /** 切块重叠 Padding 消除接缝 (默认 10) */
  tile_pad?: number | null;
}
export interface UpscaleResult {
  /** 是否处理成功 */
  success: boolean;
  /** 源输入图像路径 */
  input_path: string;
  /** 产物输出路径 */
  output_path: string;
  /** 原始物理分辨率 (宽, 高) */
  original_size: [number, number];
  /** 最终超分物理分辨率 (宽, 高) */
  output_size: [number, number];
  /** 实际收敛生效的放大倍率 */
  actual_scale: number;
  /** 端到端物理耗时 (毫秒) */
  elapsed_ms: number;
  /** 切块总数 */
  total_tiles: number;
}
export async function runUpscale48k(task: UpscaleTask): Promise<UpscaleResult> {
  return await invoke<UpscaleResult>("run_upscale_48k", { task });
}// 🛡️ 紫电 AI 桌面工坊 - 视频双语字幕专属强类型契约模块 (video-subtitle.ts)
// 100% 对齐 Rust 后端极简双轨架构 (video-subtitle / service-asr / service-translation)
import { invoke } from "@tauri-apps/api/core";
/** 视频字幕分类形态：纯生肉音频流 / 内嵌软字幕流 */
export type SubtitleSourceKind = "raw_audio" | "embedded_soft_stream";
/** 内嵌软字幕轨道元数据描述 */
export interface SubtitleTrackInfo {
  stream_index: number;
  codec_name: string;
  language?: string | null;
  title?: string | null;
  is_default: boolean;
}
/** 视频多模态探针诊断报告 */
export interface VideoProbeResult {
  video_path: string;
  duration_sec: number;
  width: number;
  height: number;
  has_audio: boolean;
  audio_streams_count: number;
  soft_tracks: SubtitleTrackInfo[];
  recommended_mode: SubtitleSourceKind;
  elapsed_ms: number;
}
/** 字幕显示模式：双语对照 / 仅目标译文 / 仅原始语言 */
export type SubtitleDisplayMode = "bilingual" | "target_only" | "source_only";
/** 封装输出模式：0.5s 无损软挂载 MKV / NVENC 显卡硬字幕压制 MP4 */
export type SubtitleOutputMode = "soft_mkv" | "hard_mp4_nvenc";
/** 领域专用术语干预表条目 */
export interface GlossaryTerm {
  source_term: string;
  target_term: string;
}
/** 单句识别与翻译结构切片 */
export interface SubtitleSegment {
  id: number;
  speaker: string;
  start_sec: number;
  end_sec: number;
  source_text: string;
  target_text: string;
}
/** 视频双语字幕转写与压制运行参数 */
export interface VideoSubtitleOptions {
  video_path: string;
  output_dir?: string | null;
  target_lang: string;
  display_mode: SubtitleDisplayMode;
  show_speaker: boolean;
  font_size_multiplier: number;
  output_mode: SubtitleOutputMode;
  hotwords?: string | null;
  glossary?: GlossaryTerm[] | null;
  source_kind?: SubtitleSourceKind | null;
  subtitle_stream_index?: number | null;
  /** 电影级柔和羽化半透明遮罩开关 (用于温润遮挡原片硬字幕) */
  mask_hardsub?: boolean;
}
/** 视频双语字幕流水线交付产物 */
export interface VideoSubtitleResult {
  success: boolean;
  output_video_path: string;
  srt_path: string;
  ass_path: string;
  json_path: string;
  total_segments: number;
  segments: SubtitleSegment[];
  elapsed_ms: number;
  error?: string | null;
}
export async function probeVideo(videoPath: string): Promise<VideoProbeResult> {
  return await invoke<VideoProbeResult>("probe_video", { videoPath });
}
export async function runVideoSubtitle(options: VideoSubtitleOptions): Promise<VideoSubtitleResult> {
  return await invoke<VideoSubtitleResult>("run_video_subtitle", { options });
}// 🛡️ 紫电 AI 桌面工坊 - 算子依赖感知与断点续传强类型契约 (dependencies.ts)
import { invoke } from "@tauri-apps/api/core";
export interface DependencyItem {
  id: string;
  name: string;
  relative_path: string;
  size_bytes: number;
  size_formatted: string;
  sha256: string;
  download_urls: string[];
  is_ready: boolean;
}
export interface DependencyProgressPayload {
  tool_id: string;
  item_id: string;
  item_name: string;
  downloaded_bytes: number;
  total_bytes: number;
  percent: number;
  phase: "waiting" | "downloading" | "verifying" | "complete";
}
/** 检查指定算子所需依赖在本地的就绪状态 */
export async function checkToolDependencies(toolId: string): Promise<DependencyItem[]> {
  return await invoke<DependencyItem[]>("check_tool_dependencies", { toolId });
}
/** 触发工具依赖批量流式下载 (支持断点续传) */
export async function downloadToolDependencies(toolId: string): Promise<boolean> {
  return await invoke<boolean>("download_tool_dependencies", { toolId });
}
/** 紧急取消当前正在执行的依赖下载 */
export async function cancelDependencyDownloads(): Promise<boolean> {
  return await invoke<boolean>("cancel_dependency_downloads");
