use image::{DynamicImage, RgbImage};
use service_upscale::pipeline::RealESRGANModel;
use service_upscale::UpscaleService;
use std::time::Instant;
fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("============================================================");
    println!("🚀 [SOTA 硬件基准] 正在对 RTX 3060 显卡执行冷/热多轮物理压测...");
    println!("============================================================\n");
    let model_path = UpscaleService::resolve_default_model_path();
    println!("🎯 [1/3] 寻址 RealESRGAN ONNX 模型: {:?}", model_path);
    let t_load_start = Instant::now();
    let mut model = RealESRGANModel::new(&model_path, 4)
        .map_err(|e| format!("🚨 CUDA 引擎初始化失败: {e}"))?;
    println!("✅ [2/3] ONNX Runtime Session 纯血 CUDA 初始化完成 (耗时: {} ms)", t_load_start.elapsed().as_millis());
    let mock_tile = DynamicImage::ImageRgb8(RgbImage::new(512, 512));
    // 1. 第 1 轮：冷启动预热 (Cold Run)
    let t_cold = Instant::now();
    let _ = model.forward_tile(&mock_tile)?;
    let cold_ms = t_cold.elapsed().as_millis();
    println!("❄️ [冷启动预热 (第1块)]: {} ms (包含 cuDNN 算子寻址与显存分配)", cold_ms);
    // 2. 连续 3 轮热推演 (Warm Runs)
    println!("\n🔥 [3/3] 启动连续 3 轮 512x512 真实切块热推演压测:");
    let mut warm_times = Vec::new();
    for round in 1..=3 {
        let t_warm = Instant::now();
        let _ = model.forward_tile(&mock_tile)?;
        let warm_ms = t_warm.elapsed().as_millis();
        warm_times.push(warm_ms);
        println!("  ├── 第 {} 块 GPU 耗时: {} ms", round, warm_ms);
    }
    let avg_warm: u128 = warm_times.iter().sum::<u128>() / warm_times.len() as u128;
    println!("\n------------------------------------------------------------");
    println!("📊 【压测结论】平均单块热推演耗时: {} ms", avg_warm);
    if avg_warm < 200 {
        println!("🏆 显卡 Tensor Core 硬件直推极速已完全激活！(4K 图像几秒即可全部完成)");
    } else {
        println!("⚠️ 热推演耗时仍在 200ms 以上，需进一步优化显存与切块调度！");
    }
    println!("------------------------------------------------------------\n");
    Ok(())
}// 🛡️ 8K 视觉超分 - 1:1 纯血模型实体与调度流水线 (pipeline.rs)
// 100% 外科手术式直译自 ai-toolkit Commit 776957e
use crate::processor::{RealESRGANPostprocessor, RealESRGANPreprocessor};
use crate::tiling::compute_grid;
use crate::{UpscaleConfig, UpscaleResult};
use core_onnx_infer::OrtInfer;
use image::{imageops, DynamicImage, ImageBuffer, Rgb, RgbImage, Rgba, RgbaImage};
use std::path::Path;
use std::time::Instant;
/// 纯血 RealESRGAN 模型实体
pub struct RealESRGANModel {
    infer: OrtInfer,
    preprocessor: RealESRGANPreprocessor,
    postprocessor: RealESRGANPostprocessor,
    scale: u32,
}
impl RealESRGANModel {
    pub fn new(model_path: &Path, scale: u32) -> Result<Self, String> {
        let infer = OrtInfer::new(model_path, Some("cuda:0"))
            .map_err(|e| format!("初始化 RealESRGAN ONNX 引擎失败: {e} ({:?})", model_path))?;
        Ok(Self {
            infer,
            preprocessor: RealESRGANPreprocessor::default(),
            postprocessor: RealESRGANPostprocessor::default(),
            scale,
        })
    }
    pub fn scale(&self) -> u32 {
        self.scale
    }
    /// 执行单块前向推理
    pub fn forward_tile(&mut self, tile_image: &DynamicImage) -> Result<DynamicImage, String> {
        let tensor = self.preprocessor.preprocess(tile_image)?;
        let out_tensor = self
            .infer
            .infer_array4(&tensor)
            .map_err(|e| format!("RealESRGAN 模型推理失败: {e}"))?;
        self.postprocessor.decode_array4(&out_tensor)
    }
}
/// 全生命周期极速流水线 (1:1 直译自原版 UpscaleTask)
pub struct UpscalePipeline {
    model: RealESRGANModel,
}
impl UpscalePipeline {
    pub fn new(model_path: &Path) -> Result<Self, String> {
        let model = RealESRGANModel::new(model_path, 4)?;
        Ok(Self { model })
    }
    pub fn run<F>(
        &mut self,
        input_path: &Path,
        output_path: &Path,
        config: &UpscaleConfig,
        progress_cb: Option<F>,
    ) -> Result<UpscaleResult, String>
    where
        F: Fn(usize, usize, &str) + Send + Sync,
    {
        let t0 = Instant::now();
        if let Some(ref cb) = progress_cb {
            cb(5, 100, "正在加载输入图像与分析物理尺寸...");
        }
        let image = image::open(input_path)
            .map_err(|e| format!("打开图像文件失败: {e} ({:?})", input_path))?;
        let (img_w, img_h) = (image.width(), image.height());
        if img_w == 0 || img_h == 0 {
            return Err("输入图像宽高不能为 0".to_string());
        }
        // 1. 智能尺寸封顶计算 (4K 极速 3840px / 8K 旗舰 8192px)
        let max_in_side = img_w.max(img_h) as f32;
        let req_scale = config.target_scale;
        let actual_scale = if (max_in_side * req_scale) > config.max_output_side as f32 {
            let capped = (config.max_output_side as f32 / max_in_side).max(1.0);
            tracing::info!("💡 [智能封顶触发] 原图: {}x{}, 收敛放大倍率为: {:.2}x", img_w, img_h, capped);
            capped
        } else {
            req_scale
        };
        let target_w = ((img_w as f32) * actual_scale).round() as u32;
        let target_h = ((img_h as f32) * actual_scale).round() as u32;
        // 2. 分离 RGBA Alpha 通道
        let has_alpha = image.color().has_alpha();
        let (rgb_image, alpha_channel) = if has_alpha {
            let rgba = image.to_rgba8();
            let mut rgb_buf = ImageBuffer::new(img_w, img_h);
            let mut alpha_buf = ImageBuffer::new(img_w, img_h);
            for (x, y, pixel) in rgba.enumerate_pixels() {
                rgb_buf.put_pixel(x, y, Rgb([pixel[0], pixel[1], pixel[2]]));
                alpha_buf.put_pixel(x, y, image::Luma([pixel[3]]));
            }
            (DynamicImage::ImageRgb8(rgb_buf), Some(DynamicImage::ImageLuma8(alpha_buf)))
        } else {
            (DynamicImage::ImageRgb8(image.to_rgb8()), None)
        };
        // 3. 计算切块网格 (默认 256 或 512)
        let tile_size = if config.tile_size == 0 { 256 } else { config.tile_size };
        let tile_pad = config.tile_pad;
        let tiles = compute_grid(img_w, img_h, tile_size, tile_pad);
        let total_tiles = tiles.len();
        let model_scale = self.model.scale();
        let mut canvas_4x: RgbImage = ImageBuffer::new(img_w * model_scale, img_h * model_scale);
        // 4. 逐块 AI GPU 矩阵直推与无缝盖章回填
        for (idx, tile) in tiles.iter().enumerate() {
            if let Some(ref cb) = progress_cb {
                let msg = format!("RTX 显卡超分推理中 ({}/{})", idx + 1, total_tiles);
                cb(idx + 1, total_tiles, &msg);
            }
            let crop_x = tile.x - tile.pad_left;
            let crop_y = tile.y - tile.pad_top;
            let crop_w = tile.w + tile.pad_left + tile.pad_right;
            let crop_h = tile.h + tile.pad_top + tile.pad_bottom;
            let sub_img = rgb_image.crop_imm(crop_x, crop_y, crop_w, crop_h);
            let tile_out = self.model.forward_tile(&sub_img)?;
            let valid_x = tile.pad_left * model_scale;
            let valid_y = tile.pad_top * model_scale;
            let valid_w = tile.w * model_scale;
            let valid_h = tile.h * model_scale;
            let tile_rgb = tile_out.to_rgb8();
            let cropped_rgb = imageops::crop_imm(&tile_rgb, valid_x, valid_y, valid_w, valid_h).to_image();
            imageops::overlay(
                &mut canvas_4x,
                &cropped_rgb,
                (tile.x * model_scale) as i64,
                (tile.y * model_scale) as i64,
            );
        }
        if let Some(ref cb) = progress_cb {
            cb(total_tiles, total_tiles, "正在调整至目标分辨率并融合透明通道...");
        }
        let raw_4x_image = DynamicImage::ImageRgb8(canvas_4x);
        // 5. 缩放到目标尺寸
        let final_rgb = raw_4x_image.resize_exact(
            target_w,
            target_h,
            image::imageops::FilterType::Triangle,
        );
        // 6. Alpha 通道融合与最终落盘
        if let Some(alpha) = alpha_channel {
            let scaled_alpha = alpha.resize_exact(
                target_w,
                target_h,
                image::imageops::FilterType::Triangle,
            );
            let luma_alpha = scaled_alpha.to_luma8();
            let rgb_buf = final_rgb.to_rgb8();
            let mut rgba_buf: RgbaImage = ImageBuffer::new(target_w, target_h);
            for (x, y, pixel) in rgba_buf.enumerate_pixels_mut() {
                let rgb_p = rgb_buf.get_pixel(x, y);
                let a_p = luma_alpha.get_pixel(x, y);
                *pixel = Rgba([rgb_p[0], rgb_p[1], rgb_p[2], a_p[0]]);
            }
            DynamicImage::ImageRgba8(rgba_buf)
                .save(output_path)
                .map_err(|e| format!("保存 RGBA 图像失败: {e} ({:?})", output_path))?;
        } else {
            final_rgb
                .save(output_path)
                .map_err(|e| format!("保存 RGB 图像失败: {e} ({:?})", output_path))?;
        }
        let elapsed_ms = t0.elapsed().as_millis() as u64;
        Ok(UpscaleResult {
            success: true,
            input_path: input_path.to_string_lossy().to_string(),
            output_path: output_path.to_string_lossy().to_string(),
            original_size: (img_w, img_h),
            output_size: (target_w, target_h),
            actual_scale,
            elapsed_ms,
            total_tiles,
        })
    }
}// 🛡️ 8K 视觉超分 - 纯血零拷贝预处理与 Rayon 多核并行解码器 (processor.rs)
// 100% 外科手术式 1:1 直译自 ai-toolkit Commit 776957e
use image::{DynamicImage, GenericImageView, ImageBuffer, RgbImage};
use ndarray::Array4;
use rayon::prelude::*;
/// 预处理配置参数
#[derive(Debug, Clone, Copy)]
pub struct RealESRGANPreprocessConfig {
    pub normalize_scale: f32,
}
impl Default for RealESRGANPreprocessConfig {
    fn default() -> Self {
        Self {
            normalize_scale: 1.0 / 255.0,
        }
    }
}
/// RealESRGAN 预处理器: DynamicImage -> [1, 3, H, W] NCHW Float32 张量
#[derive(Debug, Clone, Default)]
pub struct RealESRGANPreprocessor {
    pub config: RealESRGANPreprocessConfig,
}
impl RealESRGANPreprocessor {
    pub fn new(config: RealESRGANPreprocessConfig) -> Self {
        Self { config }
    }
    pub fn preprocess(&self, image: &DynamicImage) -> Result<Array4<f32>, String> {
        let (width, height) = image.dimensions();
        if width == 0 || height == 0 {
            return Err("输入图像尺寸不能为 0".to_string());
        }
        let rgb_img = image.to_rgb8();
        let scale = self.config.normalize_scale;
        let mut tensor = Array4::<f32>::zeros((1, 3, height as usize, width as usize));
        for y in 0..height {
            for x in 0..width {
                let pixel = rgb_img.get_pixel(x, y);
                tensor[[0, 0, y as usize, x as usize]] = pixel.0[0] as f32 * scale; // R
                tensor[[0, 1, y as usize, x as usize]] = pixel.0[1] as f32 * scale; // G
                tensor[[0, 2, y as usize, x as usize]] = pixel.0[2] as f32 * scale; // B
            }
        }
        Ok(tensor)
    }
}
/// RealESRGAN 后处理器: [1, 3, H, W] Float32 张量 -> DynamicImage
#[derive(Debug, Clone, Default)]
pub struct RealESRGANPostprocessor;
impl RealESRGANPostprocessor {
    pub fn decode_array4(&self, tensor: &Array4<f32>) -> Result<DynamicImage, String> {
        let shape = tensor.shape();
        if shape.len() != 4 || shape[1] != 3 {
            return Err(format!("张量形状不匹配，预期 [1, 3, H, W]，实际 {:?}", shape));
        }
        let height = shape[2];
        let width = shape[3];
        let slice_3d = tensor.slice(ndarray::s![0, .., .., ..]);
        let mut bytes = vec![0_u8; width * height * 3];
        bytes
            .par_chunks_mut(3)
            .enumerate()
            .for_each(|(index, pixel)| {
                let x = index % width;
                let y = index / width;
                pixel[0] = (slice_3d[[0, y, x]] * 255.0).clamp(0.0, 255.0) as u8;
                pixel[1] = (slice_3d[[1, y, x]] * 255.0).clamp(0.0, 255.0) as u8;
                pixel[2] = (slice_3d[[2, y, x]] * 255.0).clamp(0.0, 255.0) as u8;
            });
        let image: RgbImage = ImageBuffer::from_raw(width as u32, height as u32, bytes)
            .ok_or_else(|| "RGB 图像缓冲区重建失败".to_string())?;
        Ok(DynamicImage::ImageRgb8(image))
    }
}// 🛡️ 8K 视觉超分 - 零接缝智能动态切块引擎 (tiling.rs)
// 100% 外科手术式直译自 upscale_worker.py / upscale_daemon.py
use serde::{Deserialize, Serialize};
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TileInfo {
    pub x: u32,
    pub y: u32,
    pub w: u32,
    pub h: u32,
    pub pad_left: u32,
    pub pad_top: u32,
    pub pad_right: u32,
    pub pad_bottom: u32,
}
impl TileInfo {
    /// 计算包含 Padding 的输入图像裁剪区域: (crop_x, crop_y, crop_w, crop_h)
    #[inline]
    pub fn crop_rect(&self) -> (u32, u32, u32, u32) {
        let crop_x = self.x - self.pad_left;
        let crop_y = self.y - self.pad_top;
        let crop_w = self.w + self.pad_left + self.pad_right;
        let crop_h = self.h + self.pad_top + self.pad_bottom;
        (crop_x, crop_y, crop_w, crop_h)
    }
    /// 计算模型放大后的内部有效截取区域 (剔除 Padding 伪影): (valid_x, valid_y, valid_w, valid_h)
    #[inline]
    pub fn valid_scaled_rect(&self, model_scale: u32) -> (u32, u32, u32, u32) {
        let valid_x = self.pad_left * model_scale;
        let valid_y = self.pad_top * model_scale;
        let valid_w = self.w * model_scale;
        let valid_h = self.h * model_scale;
        (valid_x, valid_y, valid_w, valid_h)
    }
    /// 计算在全局 4x 目标画布上的贴图起始坐标: (paste_x, paste_y)
    #[inline]
    pub fn canvas_paste_pos(&self, model_scale: u32) -> (u32, u32) {
        (self.x * model_scale, self.y * model_scale)
    }
}
/// 智能网格切块计算器
/// 1:1 对齐 Python 原版 compute_grid 算法
pub fn compute_grid(img_w: u32, img_h: u32, tile_size: u32, tile_pad: u32) -> Vec<TileInfo> {
    let mut tiles = Vec::new();
    let mut y = 0;
    while y < img_h {
        let h = tile_size.min(img_h - y);
        let mut x = 0;
        while x < img_w {
            let w = tile_size.min(img_w - x);
            let pad_left = tile_pad.min(x);
            let pad_top = tile_pad.min(y);
            let pad_right = tile_pad.min(img_w.saturating_sub(x + w));
            let pad_bottom = tile_pad.min(img_h.saturating_sub(y + h));
            tiles.push(TileInfo {
                x,
                y,
                w,
                h,
                pad_left,
                pad_top,
                pad_right,
                pad_bottom,
            });
            x += tile_size;
        }
        y += tile_size;
    }
    tiles
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_compute_grid_basic() {
        // 测试 500x500 图像在 tile_size=256, pad=10 时的切块分布 (应为 2x2 = 4 块)
        let tiles = compute_grid(500, 500, 256, 10);
        assert_eq!(tiles.len(), 4);
        // 第 1 块 (左上角)
        let t0 = &tiles[0];
        assert_eq!(t0.x, 0);
        assert_eq!(t0.y, 0);
        assert_eq!(t0.w, 256);
        assert_eq!(t0.h, 256);
        assert_eq!(t0.pad_left, 0);
        assert_eq!(t0.pad_top, 0);
        assert_eq!(t0.pad_right, 10);
        assert_eq!(t0.pad_bottom, 10);
        assert_eq!(t0.crop_rect(), (0, 0, 266, 266));
        assert_eq!(t0.valid_scaled_rect(4), (0, 0, 1024, 1024));
        assert_eq!(t0.canvas_paste_pos(4), (0, 0));
        // 第 4 块 (右下角尾块: 244x244)
        let t3 = &tiles[3];
        assert_eq!(t3.x, 256);
        assert_eq!(t3.y, 256);
        assert_eq!(t3.w, 244);
        assert_eq!(t3.h, 244);
        assert_eq!(t3.pad_left, 10);
        assert_eq!(t3.pad_top, 10);
        assert_eq!(t3.pad_right, 0);
        assert_eq!(t3.pad_bottom, 0);
        assert_eq!(t3.crop_rect(), (246, 246, 254, 254));
        assert_eq!(t3.valid_scaled_rect(4), (40, 40, 976, 976));
        assert_eq!(t3.canvas_paste_pos(4), (1024, 1024));
    }
    #[test]
    fn test_small_image_no_split() {
        // 小于 tile_size 的图像不分块
        let tiles = compute_grid(100, 80, 256, 10);
        assert_eq!(tiles.len(), 1);
        let t = &tiles[0];
        assert_eq!(t.w, 100);
        assert_eq!(t.h, 80);
        assert_eq!(t.pad_left, 0);
        assert_eq!(t.pad_top, 0);
        assert_eq!(t.pad_right, 0);
        assert_eq!(t.pad_bottom, 0);
    }
