      <!-- 下载总体进度条 -->
      <div v-if="isDownloading" class="w-full space-y-1.5 pt-0.5">
        <div class="w-full h-2 bg-slate-100 rounded-full overflow-hidden border border-slate-200/50">
          <div
            class="h-full bg-[#18181b] transition-all duration-300 rounded-full"
            :style="{ width: `${overallPercent}%` }"
          ></div>
        </div>
        <div class="flex justify-between text-[10px] font-mono text-slate-400 font-bold">
          <span>正在下载...</span>
          <span>{{ overallPercent }}%</span>
        </div>
      </div>
      <!-- 操作按钮组 -->
      <div class="w-full grid grid-cols-2 gap-3 pt-1">
        <button
          type="button"
          @click="handleCancel"
          class="py-3 px-4 rounded-2xl bg-[#f4f4f5] hover:bg-[#e4e4e7] text-slate-800 font-bold text-xs transition-all active:scale-95 cursor-pointer flex items-center justify-center shadow-sm"
        >
          取消
        </button>
        <button
          type="button"
          :disabled="isDownloading"
          @click="handleStartDownload"
          class="py-3 px-4 rounded-2xl bg-[#18181b] hover:bg-[#27272a] disabled:bg-slate-700 text-white font-bold text-xs transition-all active:scale-95 cursor-pointer flex items-center justify-center gap-1.5 shadow-md"
        >
          <Loader2 v-if="isDownloading" :size="14" class="animate-spin" />
          <span>{{ isDownloading ? `正在下载 (${overallPercent}%)...` : '立即下载' }}</span>
        </button>
      </div>
    </div>
  </div>
</template>import { ref, onMounted } from 'vue'
import { getCurrentWebviewWindow } from '@tauri-apps/api/webviewWindow'
// 🛡️ 辅助嗅探：当前是否运行在真实的 Tauri 桌面物理宿主环境中
const isTauriEnv = () => typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window
export function useTauriWindow() {
  const 是否已置顶 = ref(false)
  const 是否已最大化 = ref(false)
  const 初始化窗口状态 = async () => {
    if (!isTauriEnv()) return
    try {
      const 物理窗口 = getCurrentWebviewWindow()
      是否已置顶.value = await 物理窗口.isAlwaysOnTop()
      是否已最大化.value = await 物理窗口.isMaximized()
    } catch (e) {
      console.warn('⚠️ 获取物理窗口状态失败:', e)
    }
  }
  const 触发最小化 = async () => {
    if (!isTauriEnv()) return
    try {
      const 物理窗口 = getCurrentWebviewWindow()
      await 物理窗口.minimize()
    } catch (e) {
      console.warn('⚠️ 最小化失败:', e)
    }
  }
  const 触发最大化还原 = async () => {
    if (!isTauriEnv()) return
    try {
      const 物理窗口 = getCurrentWebviewWindow()
      const 当前最大化 = await 物理窗口.isMaximized()
      if (当前最大化) {
        await 物理窗口.unmaximize()
        是否已最大化.value = false
      } else {
        await 物理窗口.maximize()
        是否已最大化.value = true
      }
    } catch (e) {
      console.warn('⚠️ 最大化/还原失败:', e)
    }
  }
  const 触发关闭 = async () => {
    if (!isTauriEnv()) return
    try {
      const 物理窗口 = getCurrentWebviewWindow()
      await 物理窗口.close()
    } catch (e) {
      console.warn('⚠️ 关闭窗口失败:', e)
    }
  }
  const 触发置顶切换 = async () => {
    if (!isTauriEnv()) return
    try {
      const 物理窗口 = getCurrentWebviewWindow()
      const 新状态 = !是否已置顶.value
      await 物理窗口.setAlwaysOnTop(新状态)
      是否已置顶.value = 新状态
    } catch (e) {
      console.warn('⚠️ 置顶失败:', e)
    }
  }
  onMounted(() => {
    初始化窗口状态()
  })
  return {
    是否已置顶,
    是否已最大化,
    触发最小化,
    触发最大化还原,
    触发关闭,
    触发置顶切换
  }
}// 🛡️ 紫电 AI 桌面工坊 - 根级契约转发桥接 (bindings.ts)
