        assert!(temp_dir.join("test_book.docx").exists());
        // 7. BMP -> PDF
        let bmp_file = temp_dir.join("test_img.bmp");
        let mut mock_bmp = vec![0u8; 54 + 4 * 2];
        mock_bmp[0] = b'B'; mock_bmp[1] = b'M';
